    FROM PERFORMANCE p
    WHERE p.performer_id = NEW.performer_id
      AND ((NEW.start_time BETWEEN p.start_time AND p.end_time)
        OR (NEW.end_time BETWEEN p.start_time AND p.end_time)
        OR (p.start_time BETWEEN NEW.start_time AND NEW.end_time));

    IF performer_conflict > 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Performer is already scheduled for another performance at this time';
    END IF;

    -- 5. Ensure the duration does not exceed 3 hours
    IF TIMESTAMPDIFF(MINUTE, NEW.start_time, NEW.end_time) > 180 THEN
		SIGNAL SQLSTATE '45000'
		SET MESSAGE_TEXT = 'Performance duration cannot exceed 3 hours';
	END IF;
    
END;$$


USE `festival`$$
DROP TRIGGER IF EXISTS `trg_performance_enforce_intervals_before_insert` $$
USE `festival`$$
CREATE DEFINER = CURRENT_USER TRIGGER `festival`.`trg_performance_enforce_intervals_before_insert`
BEFORE INSERT ON `PERFORMANCE`
FOR EACH ROW
BEGIN
    DECLARE prev_end_time DATETIME;
    DECLARE next_start_time DATETIME;
    DECLARE interval_before INT;
    DECLARE interval_after INT;

    -- 1. Find end time of the last performance before the current one in the same event
    SELECT MAX(end_time) INTO prev_end_time
    FROM PERFORMANCE
    WHERE event_id = NEW.event_id
      AND end_time < NEW.start_time;

    -- 2. Find start time of the next performance after the current one in the same event
    SELECT MIN(start_time) INTO next_start_time
    FROM PERFORMANCE
    WHERE event_id = NEW.event_id
      AND start_time > NEW.end_time;

    -- 3. Validate interval with the previous performance
    IF prev_end_time IS NOT NULL THEN
        SET interval_before = TIMESTAMPDIFF(MINUTE, prev_end_time, NEW.start_time);

        IF interval_before < 5 THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Interval between performances must be at least 5 minutes';
        END IF;

        IF interval_before > 30 THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Interval between performances cannot exceed 30 minutes';
        END IF;
    END IF;

    -- 4. Validate interval with the next performance
    IF next_start_time IS NOT NULL THEN
        SET interval_after = TIMESTAMPDIFF(MINUTE, NEW.end_time, next_start_time);

        IF interval_after < 5 THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Interval between performances must be at least 5 minutes';
        END IF;

        IF interval_after > 30 THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Interval between performances cannot exceed 30 minutes';
        END IF;
    END IF;
END;$$


USE `festival`$$
DROP TRIGGER IF EXISTS `trg_performance_limit_consecutive_years_before_insert` $$
USE `festival`$$
CREATE DEFINER = CURRENT_USER TRIGGER `festival`.`trg_performance_limit_consecutive_years_before_insert`
BEFORE INSERT ON `PERFORMANCE`
FOR EACH ROW
BEGIN
    DECLARE performer_id_to_check INT;
    DECLARE consecutive_years INT;
    DECLARE festival_year INT;

    -- 1. Store performer_id from the new row
    SET performer_id_to_check = NEW.performer_id;

    -- 2. Get the year of the festival for the new performance
    SELECT f.year INTO festival_year
    FROM EVENT e
    JOIN FESTIVAL f ON e.festival_id = f.festival_id
    WHERE e.event_id = NEW.event_id;

    -- 3. Check if performer participated in the previous 3 consecutive years
    SELECT COUNT(DISTINCT f.year) INTO consecutive_years
    FROM PERFORMANCE p
    JOIN EVENT e ON p.event_id = e.event_id
    JOIN FESTIVAL f ON e.festival_id = f.festival_id
    WHERE p.performer_id = performer_id_to_check
      AND f.year BETWEEN (festival_year - 3) AND (festival_year - 1)
    GROUP BY p.performer_id
    HAVING COUNT(DISTINCT f.year) = 3
       AND MIN(f.year) = festival_year - 3
       AND MAX(f.year) = festival_year - 1;

    -- 4. If true, prevent the insert
    IF consecutive_years = 3 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Performer cannot participate for more than 3 consecutive years';
    END IF;
END;$$


USE `festival`$$
