END;$$


USE `festival`$$
DROP TRIGGER IF EXISTS `trg_resale_validate_seller_before_insert` $$
USE `festival`$$
CREATE DEFINER = CURRENT_USER TRIGGER `festival`.`trg_resale_validate_seller_before_insert`
BEFORE INSERT ON `RESALE_SELLER_QUEUE`
FOR EACH ROW
BEGIN
    DECLARE ticket_owner INT;
    DECLARE is_activated BOOLEAN;
    DECLARE already_listed BOOLEAN;

    -- 1. Check that the seller is the owner of the ticket
    SELECT visitor_id, is_activated
    INTO ticket_owner, is_activated
    FROM TICKET
    WHERE ticket_id = NEW.ticket_id;

    IF ticket_owner != NEW.visitor_id THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Only the ticket owner can resell a ticket';
    END IF;

    -- 2. Check that the ticket has not been activated
    IF is_activated = 1 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Activated tickets cannot be resold';
    END IF;

    -- 3. Check that the ticket is not already listed for resale
    SELECT COUNT(*) > 0 INTO already_listed
    FROM RESALE_SELLER_QUEUE
    WHERE ticket_id = NEW.ticket_id;

    IF already_listed THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Ticket is already listed for resale';
    END IF;
END;$$


USE `festival`$$
DROP TRIGGER IF EXISTS `trg_resale_auto_transaction_after_insert` $$
USE `festival`$$
CREATE DEFINER = CURRENT_USER TRIGGER `festival`.`trg_resale_auto_transaction_after_insert`
AFTER INSERT ON `RESALE_SELLER_QUEUE`
FOR EACH ROW
BEGIN
    DECLARE buyer_id INT;
    DECLARE buyer_queue_id INT;
    DECLARE v_ticket_category VARCHAR(45);

    -- 1. Get the category of the listed ticket
    SELECT category INTO v_ticket_category
    FROM TICKET
    WHERE ticket_id = NEW.ticket_id;

    -- 2. Find the earliest interested buyer in the queue for that category
    SELECT visitor_id, queue_id INTO buyer_id, buyer_queue_id
    FROM RESALE_BUYER_QUEUE
    WHERE ticket_category = v_ticket_category
    ORDER BY interest_date ASC
    LIMIT 1;

    -- 3. If a buyer exists, complete the resale transaction
    IF buyer_id IS NOT NULL THEN
        -- a. Assign ticket to the buyer
        UPDATE TICKET
        SET visitor_id = buyer_id
        WHERE ticket_id = NEW.ticket_id;

        -- b. Remove buyer from the queue
        DELETE FROM RESALE_BUYER_QUEUE
        WHERE queue_id = buyer_queue_id;

        -- c. Remove seller from the queue
        DELETE FROM RESALE_SELLER_QUEUE
        WHERE queue_id = NEW.queue_id;
    END IF;
END;$$


USE `festival`$$
DROP TRIGGER IF EXISTS `trg_resale_enforce_fifo_before_delete` $$
USE `festival`$$
CREATE DEFINER = CURRENT_USER TRIGGER `festival`.`trg_resale_enforce_fifo_before_delete`
BEFORE DELETE ON `RESALE_SELLER_QUEUE`
FOR EACH ROW
BEGIN
    DECLARE oldest_listing_id INT;

    -- 1. Get the queue_id of the oldest ticket listing (FIFO)
    SELECT queue_id INTO oldest_listing_id
    FROM RESALE_SELLER_QUEUE
    ORDER BY listing_date ASC
    LIMIT 1;

    -- 2. Ensure only the oldest listing is being deleted
    IF OLD.queue_id != oldest_listing_id THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Tickets must be sold in FIFO order';
    END IF;
END;$$


USE `festival`$$
DROP TRIGGER IF EXISTS `trg_event_staff_requirements_before_insert` $$
USE `festival`$$
CREATE DEFINER = CURRENT_USER TRIGGER `festival`.`trg_event_staff_requirements_before_insert`
BEFORE INSERT ON `EVENT_STAFF`
FOR EACH ROW
BEGIN
    DECLARE v_staff_type VARCHAR(45);
    DECLARE venue_capacity INT;
    DECLARE required_security_staff INT;
    DECLARE required_auxiliary_staff INT;
    DECLARE current_security_staff INT;
    DECLARE current_auxiliary_staff INT;

    -- 1. Get staff type for the new assignment
    SELECT staff_type INTO v_staff_type
    FROM STAFF
    WHERE staff_id = NEW.staff_id;

    -- Validate that the staff type is one of the allowed types.
    IF v_staff_type NOT IN ('security', 'auxiliary', 'technical') THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Invalid staff type for event assignment';
    END IF;

    -- 2. Get venue capacity for the event
    SELECT v.max_capacity INTO venue_capacity
    FROM EVENT e
    JOIN VENUE v ON e.venue_id = v.venue_id
    WHERE e.event_id = NEW.event_id;

    -- 3. Calculate required minimum staff for security and auxiliary
    SET required_security_staff = CEILING(venue_capacity * 0.05);
    SET required_auxiliary_staff = CEILING(venue_capacity * 0.02);

    -- 4. Count current assigned staff of each type for the event
    SELECT COUNT(*) INTO current_security_staff
    FROM EVENT_STAFF es
    JOIN STAFF s ON es.staff_id = s.staff_id
    WHERE es.event_id = NEW.event_id
      AND s.staff_type = 'security';

    SELECT COUNT(*) INTO current_auxiliary_staff
    FROM EVENT_STAFF es
    JOIN STAFF s ON es.staff_id = s.staff_id
    WHERE es.event_id = NEW.event_id
      AND s.staff_type = 'auxiliary';

    -- 5. Increment the count for the type being inserted.
    IF v_staff_type = 'security' THEN
        SET current_security_staff = current_security_staff + 1;
    ELSEIF v_staff_type = 'auxiliary' THEN
        SET current_auxiliary_staff = current_auxiliary_staff + 1;
    END IF;
END;$$


USE `festival`$$
DROP TRIGGER IF EXISTS `trg_event_staff_requirements_before_delete` $$
USE `festival`$$
CREATE DEFINER = CURRENT_USER TRIGGER `festival`.`trg_event_staff_requirements_before_delete`
BEFORE DELETE ON `EVENT_STAFF`
FOR EACH ROW
BEGIN
    DECLARE staff_type VARCHAR(45);
    DECLARE venue_capacity INT;
    DECLARE required_security_staff INT;
    DECLARE required_auxiliary_staff INT;
    DECLARE remaining_security_staff INT;
    DECLARE remaining_auxiliary_staff INT;

    -- 1. Get the type of staff being removed
    SELECT s.staff_type INTO staff_type
    FROM STAFF s
    WHERE s.staff_id = OLD.staff_id;

    -- 2. Get venue capacity for the event
    SELECT v.max_capacity INTO venue_capacity
    FROM EVENT e
    JOIN VENUE v ON e.venue_id = v.venue_id
    WHERE e.event_id = OLD.event_id;

    -- 3. Calculate required minimum staff
    SET required_security_staff = CEILING(venue_capacity * 0.05);
    SET required_auxiliary_staff = CEILING(venue_capacity * 0.02);

    -- 4. Count remaining staff of each type (excluding the one being removed)
    SELECT COUNT(*) INTO remaining_security_staff
    FROM EVENT_STAFF es
    JOIN STAFF s ON es.staff_id = s.staff_id
    WHERE es.event_id = OLD.event_id
      AND s.staff_type = 'security'
      AND es.staff_id != OLD.staff_id;

    SELECT COUNT(*) INTO remaining_auxiliary_staff
    FROM EVENT_STAFF es
    JOIN STAFF s ON es.staff_id = s.staff_id
    WHERE es.event_id = OLD.event_id
      AND s.staff_type = 'auxiliary'
      AND es.staff_id != OLD.staff_id;

    -- 5. Prevent deletion if it violates staffing requirements
    IF staff_type = 'security' AND remaining_security_staff < required_security_staff THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Cannot remove security staff. Minimum 5% of venue capacity is required';
    END IF;

    IF staff_type = 'auxiliary' AND remaining_auxiliary_staff < required_auxiliary_staff THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Cannot remove auxiliary staff. Minimum 2% of venue capacity is required';
    END IF;
END$$


USE `festival`$$
DROP TRIGGER IF EXISTS `trg_artist_band_validate_before_insert` $$
USE `festival`$$
CREATE DEFINER = CURRENT_USER TRIGGER `festival`.`trg_artist_band_validate_before_insert`
BEFORE INSERT ON `ARTIST_BAND`
FOR EACH ROW
BEGIN
    DECLARE is_member BOOLEAN;

    -- 1. Check that leave_date (if provided) is after join_date
    IF NEW.leave_date IS NOT NULL AND NEW.leave_date <= NEW.join_date THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Leave date must be after join date';
    END IF;

    -- 2. Check that the artist is not already a current member of the band
    SELECT COUNT(*) > 0 INTO is_member
    FROM ARTIST_BAND
    WHERE artist_id = NEW.artist_id
      AND band_id = NEW.band_id
      AND (leave_date IS NULL OR leave_date > CURRENT_DATE());

    IF is_member THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Artist is already a member of this band';
    END IF;
END$$


DELIMITER ;
